create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create type public.app_role as enum ('player','moderator','administrator');
create type public.record_status as enum ('pending','needs_evidence','accepted','rejected','withdrawn');
create type public.level_status as enum ('ranked','archived','unranked','under_review');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(username ~ '^[A-Za-z0-9_]{3,20}$'),avatar_url text check(avatar_url is null or avatar_url ~ '^https://'),bio text not null default '' check(char_length(bio)<=240),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid not null references auth.users(id) on delete cascade,role public.app_role not null default 'player',granted_by uuid references auth.users(id) on delete set null,granted_at timestamptz not null default now(),primary key(user_id,role));
create table public.levels(id uuid primary key default gen_random_uuid(),rank integer unique check(rank is null or rank>0),name text not null check(char_length(name) between 1 and 120),level_id text not null unique check(level_id ~ '^[0-9]{1,20}$'),verifier text,difficulty text not null default 'Unclassified' check(char_length(difficulty)<=60),description text check(description is null or char_length(description)<=4000),status public.level_status not null default 'unranked',video_url text check(video_url is null or video_url ~ '^https://'),thumbnail_url text check(thumbnail_url is null or thumbnail_url ~ '^https://'),notes text check(notes is null or char_length(notes)<=2000),added_by uuid references auth.users(id) on delete set null,date_verified timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.level_creators(id uuid primary key default gen_random_uuid(),level_id uuid not null references public.levels(id) on delete cascade,creator_name text not null check(char_length(creator_name) between 1 and 80),created_at timestamptz not null default now(),unique(level_id,creator_name));
create table public.record_submissions(id uuid primary key default gen_random_uuid(),player_id uuid not null references public.profiles(id) on delete restrict,level_id uuid not null references public.levels(id) on delete restrict,video_url text not null check(video_url ~ '^https://'),player_notes text check(player_notes is null or char_length(player_notes)<=1200),completion_percent smallint check(completion_percent is null or completion_percent between 1 and 100),status public.record_status not null default 'pending',review_reason text check(review_reason is null or char_length(review_reason)<=2000),reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,rank_at_acceptance integer,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index one_active_submission_per_player_level on public.record_submissions(player_id,level_id) where status in ('pending','needs_evidence','accepted');
create index levels_ranked_idx on public.levels(rank) where status='ranked'; create index levels_name_search_idx on public.levels using gin(to_tsvector('simple',name)); create index record_submissions_player_created_idx on public.record_submissions(player_id,created_at desc); create index record_submissions_review_idx on public.record_submissions(status,created_at) where status in ('pending','needs_evidence');
create table public.moderation_actions(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id) on delete set null,target_user_id uuid references auth.users(id) on delete set null,level_id uuid references public.levels(id) on delete set null,submission_id uuid references public.record_submissions(id) on delete set null,action text not null check(action in ('record_accepted','record_rejected','evidence_requested','record_withdrawn','level_created','level_updated','level_archived','rank_changed','role_granted','role_revoked','report_reviewed','setting_updated')),reason text check(reason is null or char_length(reason)<=2000),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index moderation_actions_created_idx on public.moderation_actions(created_at desc);
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references auth.users(id) on delete set null,target_user_id uuid references auth.users(id) on delete set null,level_id uuid references public.levels(id) on delete set null,submission_id uuid references public.record_submissions(id) on delete set null,reason text not null check(char_length(reason) between 5 and 2000),status text not null default 'open' check(status in ('open','reviewing','resolved','dismissed')),resolution text check(resolution is null or char_length(resolution)<=2000),reviewed_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),resolved_at timestamptz);
create index reports_status_created_idx on public.reports(status,created_at desc);
create table public.site_settings(key text primary key check(key ~ '^[a-z][a-z0-9_]{1,80}$'),value jsonb not null default '{}'::jsonb,description text,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
insert into public.site_settings(key,value,description) values('list_config','{"max_ranked_levels":150,"list_name":"The GD Hub"}','Configurable list display settings'),('community_rules','{"status":"draft","sections":[{"title":"List eligibility","body":"Placeholder — define and approve criteria before launch."},{"title":"Evidence","body":"Placeholder — define required evidence before launch."},{"title":"Appeals","body":"Placeholder — define appeal process before launch."}]}','Draft policy text; not finalized') on conflict(key) do nothing;
create or replace function private.has_role(required_roles public.app_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_roles r where r.user_id=(select auth.uid()) and r.role=any(required_roles)); $$;
revoke all on function private.has_role(public.app_role[]) from public,anon; grant usage on schema private to authenticated; grant execute on function private.has_role(public.app_role[]) to authenticated;
create or replace function private.create_profile_for_new_user() returns trigger language plpgsql security definer set search_path='' as $$ declare candidate text; begin candidate:=coalesce(nullif(new.raw_user_meta_data->>'username',''),split_part(coalesce(new.email,new.id::text),'@',1)); candidate:=regexp_replace(candidate,'[^A-Za-z0-9_]','','g'); if char_length(candidate)<3 then candidate:='player_'||left(replace(new.id::text,'-',''),10); end if; candidate:=left(candidate,11)||'_'||left(replace(new.id::text,'-',''),8); insert into public.profiles(id,username) values(new.id,candidate) on conflict(id) do nothing; insert into public.user_roles(user_id,role) values(new.id,'player') on conflict do nothing; return new; end; $$;
revoke all on function private.create_profile_for_new_user() from public,anon,authenticated; create trigger on_auth_user_created after insert on auth.users for each row execute function private.create_profile_for_new_user();
create or replace function private.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
create trigger profiles_touch before update on public.profiles for each row execute function private.touch_updated_at(); create trigger levels_touch before update on public.levels for each row execute function private.touch_updated_at(); create trigger submissions_touch before update on public.record_submissions for each row execute function private.touch_updated_at();
alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.levels enable row level security; alter table public.level_creators enable row level security; alter table public.record_submissions enable row level security; alter table public.moderation_actions enable row level security; alter table public.reports enable row level security; alter table public.site_settings enable row level security;
create policy "public read profiles" on public.profiles for select to anon,authenticated using(true); create policy "players update own profile" on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy "public read ranked levels" on public.levels for select to anon,authenticated using(status='ranked' or (select private.has_role(array['moderator','administrator']::public.app_role[]))); create policy "moderators update levels" on public.levels for update to authenticated using((select private.has_role(array['moderator','administrator']::public.app_role[]))) with check((select private.has_role(array['moderator','administrator']::public.app_role[])));
create policy "admins insert levels" on public.levels for insert to authenticated with check((select private.has_role(array['administrator']::public.app_role[])));
create policy "admins delete levels" on public.levels for delete to authenticated using((select private.has_role(array['administrator']::public.app_role[])));
create policy "public read creators for ranked levels" on public.level_creators for select to anon,authenticated using(exists(select 1 from public.levels l where l.id=level_id and (l.status='ranked' or (select private.has_role(array['moderator','administrator']::public.app_role[]))))); create policy "staff manage creators" on public.level_creators for all to authenticated using((select private.has_role(array['moderator','administrator']::public.app_role[]))) with check((select private.has_role(array['moderator','administrator']::public.app_role[])));
create policy "users read own submissions and staff read all" on public.record_submissions for select to authenticated using(player_id=(select auth.uid()) or (select private.has_role(array['moderator','administrator']::public.app_role[])));
create policy "players submit for themselves" on public.record_submissions for insert to authenticated with check(player_id=(select auth.uid()) and status='pending' and reviewed_by is null and reviewed_at is null and exists(select 1 from public.levels l where l.id=level_id and l.status='ranked'));
create policy "players withdraw own eligible submissions" on public.record_submissions for update to authenticated using(player_id=(select auth.uid()) and status in ('pending','needs_evidence')) with check(player_id=(select auth.uid()) and status='withdrawn' and reviewed_by is null and reviewed_at is null);
create policy "moderators review submissions" on public.record_submissions for update to authenticated using((select private.has_role(array['moderator','administrator']::public.app_role[]))) with check((select private.has_role(array['moderator','administrator']::public.app_role[])) and status in ('pending','needs_evidence','accepted','rejected','withdrawn'));
create policy "staff read roles" on public.user_roles for select to authenticated using((select private.has_role(array['moderator','administrator']::public.app_role[])) or user_id=(select auth.uid()));
create policy "staff read moderation audit" on public.moderation_actions for select to authenticated using((select private.has_role(array['moderator','administrator']::public.app_role[]))); create policy "staff add moderation audit" on public.moderation_actions for insert to authenticated with check((select private.has_role(array['moderator','administrator']::public.app_role[])) and actor_id=(select auth.uid()));
create policy "staff read reports" on public.reports for select to authenticated using((select private.has_role(array['moderator','administrator']::public.app_role[])) or reporter_id=(select auth.uid())); create policy "authenticated create reports" on public.reports for insert to authenticated with check(reporter_id=(select auth.uid()) and status='open' and reviewed_by is null and resolved_at is null); create policy "staff update reports" on public.reports for update to authenticated using((select private.has_role(array['moderator','administrator']::public.app_role[]))) with check((select private.has_role(array['moderator','administrator']::public.app_role[])));
create policy "public read site settings" on public.site_settings for select to anon,authenticated using(key in ('list_config','community_rules')); create policy "admins manage site settings" on public.site_settings for all to authenticated using((select private.has_role(array['administrator']::public.app_role[]))) with check((select private.has_role(array['administrator']::public.app_role[])));
grant select on public.profiles,public.levels,public.level_creators,public.site_settings to anon,authenticated; grant update(username,avatar_url,bio) on public.profiles to authenticated; grant select on public.user_roles,public.record_submissions,public.moderation_actions,public.reports to authenticated; grant insert(player_id,level_id,video_url,player_notes,completion_percent,status) on public.record_submissions to authenticated; grant update(status,review_reason,reviewed_by,reviewed_at,rank_at_acceptance) on public.record_submissions to authenticated; grant insert,update,delete on public.levels to authenticated; grant insert,update,delete on public.level_creators to authenticated; grant insert(actor_id,target_user_id,level_id,submission_id,action,reason,metadata) on public.moderation_actions to authenticated; grant insert(reporter_id,target_user_id,level_id,submission_id,reason) on public.reports to authenticated; grant update(status,resolution,reviewed_by,resolved_at) on public.reports to authenticated; grant select,update on public.site_settings to authenticated;
